from __future__ import annotations

from .common import build_mcq


def generate() -> list[dict]:
    questions: list[dict] = []
    seen: set[str] = set()

    def add_q(q_dict: dict) -> bool:
        if q_dict["question"] in seen:
            return False
        seen.add(q_dict["question"])
        questions.append(q_dict)
        return True

